static int gear(const P2D89_Provider *p){unsigned int i;p2d89_q14 sn,cs,r,x,y;p2d89_u32 ph;for(i=0U;i<32U;++i){ph=49152U+(65536U*i)/32U;p2d89_sincos_turn((p2d89_u16)ph,&sn,&cs);r=(i%4U<2U)?16384:12288;x=p2d89_mul_q14(cs,r);y=p2d89_mul_q14(sn,r);if(i==0U){if(!p2d89_i_move(p,x,y))return 0;}else if(!p2d89_i_line(p,x,y))return 0;}return p2d89_i_close(p);}
